\begin{array}{l}

\mathrm{V}_{0}=\mathrm{I}_{\mathrm{C}} \mathrm{R}_{\mathrm{C}}=2 \\

\Rightarrow \quad \mathrm{I}_{\mathrm{C}}=\frac{2}{2 \times 10^{3}}=10^{-3} \mathrm{~A} \\

\text { Current gain } \alpha=\frac{\mathrm{I}_{\mathrm{C}}}{\mathrm{I}_{\mathrm{B}}}=100 \\

\Rightarrow \quad \mathrm{I}_{\mathrm{B}}=\frac{\mathrm{I}_{\mathrm{C}}}{100}=\frac{10^{-3}}{100}=10^{-5} \mathrm{~A} \\

\quad \mathrm{~V}_{\mathrm{i}}=\mathrm{R}_{\mathrm{B}} \mathrm{I}_{\mathrm{B}} \Rightarrow \mathrm{V}_{\mathrm{i}}=1 \times 10^{3} \times 10^{-5} \\

\Rightarrow \quad \mathrm{V}_{\mathrm{i}}=10^{-2} \mathrm{~V} \Rightarrow \mathrm{V}_{\mathrm{i}}=10 \mathrm{mV}

\end{array}
